-- =============================================================================
-- Królowej Jadwigi Residence II (KRJ Apartamenty II, krj307-2) — dane inwestycji
-- (tabela pages, patrz db/schema.sql)
-- =============================================================================
--
-- Wygenerowane z analizy starego projektu kgd-group-deweloper:
--   src/components/templates/krj307-2/**
--   src/data/pages/inwestycja/krj307-2/**
--
-- Uwagi:
--   - "example" — w starym template.js NIGDY nie miał zaimportowanego
--     komponentu (dead section, jak inne "Nieznany komponent" w tym projekcie)
--     — celowo brak wpisu w src/components/investments/krj307-2/template.tsx.
--   - "Hero" — pola puste w źródle i tutaj też: to tylko pełnoekranowe wideo
--     w tle (HeroBg2.mp4) bez żadnego tekstu, nic do wyciągnięcia.
--   - "Gallery" — w źródle zdjęcia galerii były zaimportowane bezpośrednio w
--     Gallery.jsx (lokalne pliki 1/7/8/10-13/15-20.webp), nie w JSON — zgodnie
--     z regułą projektu (bez hardkodowanej treści w komponencie) wyciągnięte
--     do pola "gallery", z zachowaniem oryginalnej kolejności wyświetlania
--     (15,13,12,16,17,18,19,20,1,7,8,10,11).
--   - "Localization" (tekst) i "Map" (Leaflet) — w źródle DWIE osobne sekcje
--     z tym samym id="lokalizacja" (duplikat DOM-owy). Tu kotwica zostaje
--     tylko na pierwszej (Localization, przez hashId), Map jej nie powtarza —
--     bez zmiany widocznego zachowania (ten sam link nawigacji trafia w to
--     samo miejsce).
--   - NavBar — w źródle ikona hamburgera z biblioteki "lucide-react" (nowa
--     zależność). Zastąpiona inline SVG, jak we wszystkich innych
--     zmigrowanych inwestycjach — bez nowej zależności.
--   - "Apartaments" (i "PriceHistory") — w źródle fetch() do zewnętrznego CMS
--     (krj307-2.pl/acp/api/...) z kluczem API w Config.js. Zastąpione
--     statycznymi polami (8 apartamentów M1-M8, placeholder) zgodnie z
--     zasadą projektu (bez zewnętrznego API) — do uzupełnienia w adminie.
--   - Cta — standardPdfUrl i prospectusButtons.url wskazywały na pliki PDF
--     hostowane na krj307-2.pl/upload/... (zewnętrzne, nie zbundlowane w
--     starym repo) — zostawione puste do uzupełnienia w adminie zamiast
--     linkować do nieistniejącego już zewnętrznego zasobu.
--
-- UPSERT (ON DUPLICATE KEY UPDATE) — bezpieczne przy ponownym imporcie.
--
-- Import: mysql -u UZYTKOWNIK -p NAZWA_BAZY < db/inwestycje/krj307-2.sql
-- =============================================================================

INSERT INTO pages (slug, content) VALUES
  ('/inwestycja/krj307-2', '{"slug":"/inwestycja/krj307-2","parent":null,"template":"krj307-2","title":{"value":"KRJ Apartamenty II","editable":true,"label":"Tytuł strony"},"updatedAt":"2026-09-07","status":"published","nav":{"label":"Królowej Jadwigi Residence II","order":14},"seo":{"title":{"value":"KRJ Apartamenty II – Wola Justowska","editable":true,"label":"Tytuł SEO"},"description":{"value":"Kameralna inwestycja w Woli Justowskiej: apartamenty 4–5 pokojowe z ogródkami i tarasami, inteligentny dom i najwyższy standard wykończenia.","editable":true,"label":"Opis SEO"},"keywords":["KRJ Apartamenty II","apartamenty Wola Justowska","mieszkania 4 pokojowe Kraków","inteligentny dom","apartamenty z tarasem"],"canonical":"https://kgd-group.pl/inwestycja/krj307-2","robots":{"index":true,"follow":true},"author":"KGD Group","ogTitle":"KRJ Apartamenty II – Wola Justowska","ogDescription":"Kameralna inwestycja w Woli Justowskiej: apartamenty 4–5 pokojowe z ogródkami i tarasami, inteligentny dom i najwyższy standard wykończenia.","ogImage":"https://kgd-group.pl/assets/images/og-image-kgd.jpg","ogType":"website","ogUrl":"https://kgd-group.pl/inwestycja/krj307-2","ogSiteName":"KGD Group","ogLocale":"pl_PL","twitterCard":"summary_large_image","twitterTitle":"KRJ Apartamenty II – Wola Justowska","twitterDescription":"Kameralna inwestycja w Woli Justowskiej: apartamenty 4–5 pokojowe z ogródkami i tarasami, inteligentny dom i najwyższy standard wykończenia.","twitterImage":"https://kgd-group.pl/assets/images/og-image-kgd.jpg","language":"pl","structuredData":[{"type":"WebPage"}]},"sections":[{"id":"navbar","component":"NavBar","type":"section","label":"Nawigacja","fields":{"menu":{"value":[{"name":"O INWESTYCJI","path":"#o_inwestycji"},{"name":"APARTAMENTY","path":"#apartamenty"},{"name":"UDOGODNIENIA","path":"#udogodnienia"},{"name":"LOKALIZACJA","path":"#lokalizacja"},{"name":"GALERIA","path":"#galeria"},{"name":"DEWELOPER","path":"/"},{"name":"KONTAKT","path":"#kontakt"}],"editable":true,"label":"Linki nawigacji"},"phone":{"value":"12 352 15 00","editable":true,"label":"Telefon"}}},{"id":"hero","component":"Hero","type":"section","label":"Hero","fields":{}},{"id":"aboutus","component":"AboutUs","type":"section","label":"O inwestycji","fields":{"header":{"value":"Apartamety Królowej Jadwigi","editable":true,"label":"Nagłówek"},"text":{"value":"II etap prestiżowej inwestycji w najbardziej pożądanej dzielnicy Krakowa. W sercu Woli Justowskiej powstaje kolejna ekskluzywna enklawa, gdzie natura spotyka się z miejskim luksusem. To miejsce stworzone z myślą o tych, którzy cenią sobie kameralną atmosferę w połączeniu z wygodnym i szybkim dostępem do wszystkich udogodnień miejskiego życia. Zaledwie kilka minut dzieli Cię od tętniącego życiem Starego Miasta, podczas gdy otaczająca zieleń tworzy atmosferę prywatnego azylu.","editable":true,"label":"Tekst"}}},{"id":"features","component":"Features","type":"section","label":"Udogodnienia","fields":{"header":{"value":"Wyjątkowe Apartamenty","editable":true,"label":"Nagłówek"},"features":{"value":[{"title":"Wentylacja","span":"Mechaniczna nawiewno-wywiewna z rekuperatorem","icon":"fan"},{"title":"Klimatyzacja","span":"Wewnętrzna instalacja w salonie i sypialniach","icon":"clima"},{"title":"Ogrzewanie","span":"Ogrzewanie podłogowe w całym apartamencie,","icon":"heating"},{"title":"Inteligenty dom","span":"Instalacja BMS","icon":"smarthome"}],"editable":true,"label":"Cechy"}}},{"id":"apartaments","component":"Apartaments","type":"section","label":"Apartamenty","fields":{"header":{"value":"APARTAMENTY","editable":true,"label":"Nagłówek"},"disclaimer1":{"value":"W prezentowanej cenie każdego mieszkania/segmentu uwzględniono miejsce do wyłącznego korzystania, wydzielone z części wspólnej, o powierzchni 12,5 m².","editable":true,"label":"Zastrzeżenie 1"},"disclaimer2":{"value":"Klient przy zakupie ponosi 50% kosztów notarialnych i opłat sądowych, gdy zawierana jest umowa deweloperska, a 100% tych kosztów w przypadku umowy przedwstępnej i/lub umowy przenoszącej własność.","editable":true,"label":"Zastrzeżenie 2"},"apartments":{"value":[{"unit":"M1","isGarage":false,"rooms":"4","area":"95m2","garden":"20m2","pricePerM2":"-","price":"-","status":"Wolny","images":[],"pdfUrl":""},{"unit":"M2","isGarage":false,"rooms":"4","area":"95m2","garden":"20m2","pricePerM2":"-","price":"-","status":"Wolny","images":[],"pdfUrl":""},{"unit":"M3","isGarage":false,"rooms":"4","area":"95m2","garden":"20m2","pricePerM2":"-","price":"-","status":"Wolny","images":[],"pdfUrl":""},{"unit":"M4","isGarage":false,"rooms":"4","area":"95m2","garden":"20m2","pricePerM2":"-","price":"-","status":"Wolny","images":[],"pdfUrl":""},{"unit":"M5","isGarage":false,"rooms":"4","area":"95m2","garden":"20m2","pricePerM2":"-","price":"-","status":"Wolny","images":[],"pdfUrl":""},{"unit":"M6","isGarage":false,"rooms":"4","area":"95m2","garden":"20m2","pricePerM2":"-","price":"-","status":"Wolny","images":[],"pdfUrl":""},{"unit":"M7","isGarage":false,"rooms":"4","area":"95m2","garden":"20m2","pricePerM2":"-","price":"-","status":"Wolny","images":[],"pdfUrl":""},{"unit":"M8","isGarage":false,"rooms":"4","area":"95m2","garden":"20m2","pricePerM2":"-","price":"-","status":"Wolny","images":[],"pdfUrl":""}],"editable":true,"label":"Apartamenty (placeholder — do uzupełnienia realnymi danymi/cenami w panelu admina)"},"labels":{"value":{"colUnit":"Nr Budynku","colRooms":"Liczba pokoi","colArea":"Powierzchnia","colGarden":"Ogród/Taras","colPricePerM2":"Cena za m","colPrice":"Cena","colStatus":"Status","colGallery":"Wizualizazcje","colDocuments":"Dokumenty","seeMore":"Zobacz","unitCard":"Karta lokalu","priceHistory":"Historia cen"},"editable":true,"label":"Etykiety"}}},{"id":"cta","component":"Cta","type":"section","label":"Cta","fields":{"standardHeader":{"value":"STANDARD WYKOŃCZENIA","editable":true,"label":"Nagłówek standardu"},"standardText":{"value":"Nowoczesna forma, naturalne materiały i perfekcyjnie dopracowane detale – Poznaj Królowej Jadwigi Rezidence II zachwyca dziś i przez lata.","editable":true,"label":"Tekst standardu"},"standardPdfUrl":{"value":"","editable":true,"label":"Plik standardu wykończenia (PDF)"},"buttonLabel":{"value":"Dowiedz się więcej","editable":true,"label":"Etykieta przycisku standardu"},"prospectusHeader":{"value":"PROSPEKT INFORMACYJNY","editable":true,"label":"Nagłówek prospektu"},"prospectusText":{"value":"Cała inwestycja w jednym miejscu – standard i harmonogram oraz kwestie prawne. Poznaj Królowej Jadwigi Rezidence II świadomie, zanim podejmiesz decyzję. Dowiedz się więcej.","editable":true,"label":"Tekst prospektu"},"prospectusButtons":{"value":[{"label":"Budynek m1 do m4","url":""},{"label":"Budynek m5 do m8","url":""}],"editable":true,"label":"Przyciski prospektu (PDF)"}}},{"id":"localization","component":"Localization","type":"section","label":"Lokalizacja (tekst)","hashId":"lokalizacja","fields":{"header":{"value":"Lokalizacja","editable":true,"label":"Nagłówek"},"text1":{"value":"Drugi etap Residence Królowej Jadwigi powstaje przy ulicy Królowej Jadwigi 307, w ekskluzywnej dzielnicy – Woli Justowskiej – miejscu, które od lat pozostaje synonimem prestiżu i komfortowego życia. Ta wyjątkowa lokalizacja to starannie wyselekcjonowana przestrzeń, gdzie elegancka zabudowa willowa współgra z bogactwem terenów zielonych.","editable":true,"label":"Tekst 1"},"text2":{"value":"Usytuowanie inwestycji zostało przemyślane w najdrobniejszych szczegółach – zaledwie kilka minut dzieli mieszkańców od historycznego centrum Krakowa, podczas gdy okoliczne tereny rekreacyjne zachęcają do aktywnego wypoczynku. Rozwinięta infrastruktura, w połączeniu z kameralnym charakterem dzielnicy, tworzy idealne warunki do życia dla najbardziej wymagających mieszkańców.","editable":true,"label":"Tekst 2"}}},{"id":"map","component":"Map","type":"section","label":"Mapa","fields":{"points":{"value":[{"name":"Królowej Jadwigi residence II","position":[50.07208138080224,19.86051714